import {amount,today,uid} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>(n/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const categories=['Зарплата','Аванс','Премия','Отпускные','Больничный / командировка','Кэшбэк','Проценты','Дивиденды','Прочее'];
const salary=c=>categories.slice(0,5).includes(c);
export function demoFinance(){
 const incomes=[];for(const y of [2025,2026])for(let m=1;m<=(y===2026?9:12);m++){const month=`${y}-${String(m).padStart(2,'0')}`;for(const [category,value,day] of [['Зарплата',51000+(m%3)*1800,10],['Аванс',26000,25],['Кэшбэк',600+m*120,12],['Проценты',1800+m*80,20]])incomes.push({id:uid(),category,amount:Math.round(value*(y===2026?1.12:1)*100),date:`${month}-${day}`,month,bank:'Т-Банк',note:'Пример'});if(m===5)incomes.push({id:uid(),category:'Премия',amount:1800000,date:`${month}-15`,month,bank:'Сбер',note:'Пример'});}
 return {incomes,sales:[{id:uid(),name:'Визитки · заказ 120 шт.',date:'2026-09-18',revenue:72000,cost:30000,received:72000,quantity:120,productId:''},{id:uid(),name:'USB-светильник',date:'2026-09-22',revenue:180000,cost:78000,received:120000,quantity:3,productId:''},{id:uid(),name:'Пузырьчатая плёнка',date:'2026-08-12',revenue:140000,cost:64000,received:140000,quantity:2,productId:''}],stock:[{id:uid(),name:'USB-светильник',quantity:8,cost:26000,price:60000,source:'OZON'},{id:uid(),name:'Пузырьчатая плёнка',quantity:5,cost:32000,price:70000,source:'WB'},{id:uid(),name:'Обложка для паспорта',quantity:12,cost:8500,price:25000,source:'Закупка'}],accounts:[{id:uid(),name:'Т-Банк · карта',balance:4250000},{id:uid(),name:'Сбер · накопительный',balance:18000000},{id:uid(),name:'OZON · карта',balance:730000}],reserved:2500000,credit:1200000,mortgages:[{id:uid(),name:'Ипотека · пример',initial:272000000,balance:23337543,payments:[]}],family:[{id:uid(),name:'Расчёты с бабулей · пример',balance:16000000,payments:[]}]};
}
export function cardTotals(order){const cost=order.quantity*order.unitCost,revenue=order.actualQuantity*order.unitPrice;return {cost,revenue,plannedProfit:revenue-cost,profit:order.received-cost,debt:Math.max(0,revenue-order.received),overpayment:Math.max(0,order.received-revenue)};}
export function financeTotals(data,year,month='all',kind='all'){
 const matches=period=>period.startsWith(year+'-')&&(month==='all'||period===`${year}-${month}`);
 const incomes=data.incomes.filter(x=>matches(x.month)&&(kind==='all'||x.category===kind));const sales=kind==='all'||kind==='Продажи'?[...data.sales,...(data.cards||[]).map(x=>({...x,...cardTotals(x),name:'Визитки · '+x.name,card:true}))].filter(x=>matches(x.date.slice(0,7))):[];
 const employment=incomes.filter(x=>salary(x.category)).reduce((n,x)=>n+x.amount,0),profit=sales.reduce((n,x)=>n+x.received-x.cost,0),other=incomes.filter(x=>!salary(x.category)).reduce((n,x)=>n+x.amount,0);
 return {total:employment+other+profit,salary:employment,other:other+profit,profit,incomes,sales};
}
export function startFinance(root,user){
 const link=document.createElement('link');link.rel='stylesheet';link.href='/finance.css';document.head.append(link);
 const key='money-finance-prototype-v1-'+user.id;let data;try{data=JSON.parse(localStorage.getItem(key));if(!data?.incomes||!data?.stock)throw Error();}catch{data=demoFinance();}
 if(!data.cards){data.cards=data.sales.filter(x=>x.name.startsWith('Визитки')).map(x=>({id:x.id,name:'Тестовый заказчик',date:x.date,quantity:x.quantity,actualQuantity:x.quantity,unitCost:Math.round(x.cost/x.quantity),unitPrice:Math.round(x.revenue/x.quantity),received:x.received,note:''}));data.sales=data.sales.filter(x=>!x.name.startsWith('Визитки'));}
 let tab='overview',year=2026,month='all',kind='all';const modal=document.getElementById('modal');
 const save=()=>{try{localStorage.setItem(key,JSON.stringify(data));render();}catch{alert('Не удалось сохранить изменения на устройстве.');}};
 const btn=(action,label,extra='')=>`<button data-fin="${action}" ${extra}>${label}</button>`;
 const options=(list,selected)=>list.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
 const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
 function form(title,body,submit,apply){modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button id="fin-close" aria-label="Закрыть">✕</button></div><form class="modal-body">${body}<p class="error" role="alert"></p><div class="modal-buttons"><button type="button" id="fin-cancel">Отмена</button><button type="submit" class="primary">${submit}</button></div></form>`;modal.showModal();modal.querySelector('#fin-close').onclick=modal.querySelector('#fin-cancel').onclick=()=>modal.close();modal.querySelector('form').onsubmit=ev=>{ev.preventDefault();try{apply(new FormData(ev.target));modal.close();save();}catch(e){modal.querySelector('.error').textContent=e.message;}};}
 function overview(){const t=financeTotals(data,year,month),months=[...new Set([...t.incomes.map(x=>x.month),...t.sales.map(x=>x.date.slice(0,7))])],n=months.length||1;
 const prev=financeTotals(data,year-1,month);const cutoff=month==='all'?Math.max(0,...months.map(x=>Number(x.slice(5)))):Number(month);const comparable=month==='all'?Array.from({length:cutoff},(_,i)=>financeTotals(data,year-1,String(i+1).padStart(2,'0')).total).reduce((a,b)=>a+b,0):prev.total;
 const growth=comparable?((t.total-comparable)/comparable*100).toFixed(1):null;const vals=Array.from({length:12},(_,i)=>financeTotals(data,year,String(i+1).padStart(2,'0'))),max=Math.max(1,...vals.map(x=>x.total));
 const groups=new Map();for(const x of t.incomes)groups.set(x.category,(groups.get(x.category)||0)+x.amount);if(t.sales.length)groups.set('Прибыль от продаж',t.profit);
 return `<div class="fin-kpis">${[['Всего доходов',t.total],['Зарплата и выплаты',t.salary],['Без зарплаты',t.other],['Прибыль от продаж',t.profit]].map(([l,v])=>`<article class="panel"><span class="muted">${l}</span><strong>${rub(v)}</strong></article>`).join('')}</div><div class="fin-duo"><section class="panel"><div class="row between"><h3>Доходы по месяцам</h3><span class="muted">${year}</span></div><div class="fin-chart" role="img" aria-label="Доход по месяцам: зарплата зелёным, остальные доходы синим">${vals.map((v,i)=>`<button class="fin-bar" data-fin="month" data-month="${String(i+1).padStart(2,'0')}" aria-label="${i+1} месяц: ${rub(v.total)}"><div class="fin-bar-space"><span class="fin-bar-other" style="height:${Math.max(0,(v.total-v.salary)/max*100)}%"></span><span style="height:${v.salary/max*100}%"></span></div><small>${['Я','Ф','М','А','М','И','И','А','С','О','Н','Д'][i]}</small></button>`).join('')}</div><p class="muted">● Зарплата и выплаты · <span class="fin-blue">● Остальные доходы</span></p><p class="footnote">Нажмите на месяц, чтобы открыть подробности.</p></section><section class="panel"><h3>Источники дохода</h3>${[...groups].sort((a,b)=>b[1]-a[1]).map(([c,a])=>`<button class="fin-source" data-fin="category" data-kind="${c==='Прибыль от продаж'?'Продажи':esc(c)}"><span>${esc(c)}</span><strong>${rub(a)}</strong></button>`).join('')}</section></div><div class="fin-duo"><section class="panel"><h3>Сравнение и среднее</h3><p class="fin-metric">${growth===null?'Нет данных для сравнения':`${Number(growth)>0?'+':''}${growth}%`}</p><p class="muted">К тому же периоду ${year-1} года${month==='all'?' · январь–'+cutoff:''}</p><p class="footnote">Среднее за ${n} мес. с записями: <b>${rub(Math.round(t.total/n))}</b></p></section><section class="panel"><h3>Деньги и обязательства</h3>${accountSummary()}${btn('accounts','Открыть счета →','class="textlink"')}</section></div>`;
 }
 function accountSummary(){const balance=data.accounts.reduce((n,x)=>n+x.balance,0);return `<div class="fin-line"><span>На счетах</span><b>${rub(balance)}</b></div><div class="fin-line"><span>Долг по кредиткам</span><b>${rub(data.credit)}</b></div><div class="fin-line"><span>Зарезервировано</span><b>${rub(data.reserved)}</b></div><div class="fin-line"><span>Свободно</span><b>${rub(balance-data.credit-data.reserved)}</b></div>`;}
 function incomesView(){const t=financeTotals(data,year,month,kind),rows=[...t.incomes.map(x=>({...x,label:x.category})),...t.sales.map(x=>({...x,label:'Продажи · '+x.name,amount:x.received-x.cost,month:x.date.slice(0,7),sale:true}))].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="row between"><h3>Поступления · ${rub(t.total)}</h3>${btn('income','＋ Добавить','class="primary"')}</div><p class="footnote">Прибыль от продаж рассчитывается автоматически. В тестовом режиме: получено минус себестоимость всего заказа.</p><label class="fin-filter">Источник<select id="fin-kind">${options(['all',...categories,'Продажи'],kind).replace('>all<','>Все источники<')}</select></label><section class="panel">${rows.map(x=>`<div class="fin-entry"><div class="grow"><strong>${esc(x.label)}</strong><p class="muted">${esc(x.date)} · за ${esc(x.month)}${x.bank?' · '+esc(x.bank):''}</p>${x.note?`<p class="muted">${esc(x.note)}</p>`:''}</div><b>${rub(x.amount)}</b>${!x.sale?btn('edit-income','✎',`data-id="${x.id}" aria-label="Изменить поступление"`):''}</div>`).join('')||'<p class="muted">За этот период записей нет. Добавьте поступление.</p>'}</section>`;}
 function salesView(){return `<div class="row between"><h3>Продажи</h3>${btn('sale','＋ Продажа','class="primary"')}</div><p class="footnote">Все тестовые продажи. Частичная оплата видна отдельно, прибыль отражается в месяце продажи.</p><div class="fin-cards">${data.sales.map(x=>`<article class="panel"><span class="badge ${x.received>=x.revenue?'complete':''}">${x.received>=x.revenue?'Оплачено':'Есть долг'}</span><h3>${esc(x.name)}</h3><p class="muted">${x.date} · ${x.quantity} шт.</p><div class="fin-line"><span>Продажа</span><b>${rub(x.revenue)}</b></div><div class="fin-line"><span>Получено</span><b>${rub(x.received)}</b></div><div class="fin-line"><span>Себестоимость</span><b>${rub(x.cost)}</b></div><div class="fin-line"><span>Фактическая прибыль</span><b>${rub(x.received-x.cost)}</b></div>${x.received<x.revenue?btn('sale-pay',`Получить остаток ${rub(x.revenue-x.received)}`,`data-id="${x.id}" class="secondary full"`):''}</article>`).join('')}</div>`;}
 function cardsView(){const orders=[...data.cards].sort((a,b)=>b.date.localeCompare(a.date)||a.name.localeCompare(b.name,'ru')),sum=orders.reduce((a,x)=>{const t=cardTotals(x);a.received+=x.received;a.cost+=t.cost;a.profit+=t.profit;a.debt+=t.debt;return a;},{received:0,cost:0,profit:0,debt:0});return `<div class="row between"><h3>Визитки · ${orders.length} заказов</h3>${btn('card','＋ Заказ','class="primary"')}</div><p class="footnote">Поля и расчёты как на листе «Продажи»: заказанное и фактическое количество учитываются отдельно.</p><div class="fin-kpis">${[['Получено',sum.received],['Себестоимость',sum.cost],['Доход (факт)',sum.profit],['Осталось получить',sum.debt]].map(([l,v])=>`<article class="panel"><span class="muted">${l}</span><strong>${rub(v)}</strong></article>`).join('')}</div><div class="fin-cards">${orders.map(x=>{const t=cardTotals(x);return `<article class="panel"><span class="badge ${!t.debt?'complete':''}">${t.debt?'Есть долг':t.overpayment?'Переплата':'Оплачено'}</span><h3>${esc(x.name)}</h3><p class="muted">${esc(x.date)}</p>${[['Кол-во',x.quantity+' шт.'],['Кол-во (факт)',x.actualQuantity+' шт.'],['Цена закупки за 1 шт.',rub(x.unitCost)],['Цена за 1 шт. с наценкой',rub(x.unitPrice)],['Себестоимость',rub(t.cost)],['Должны (факт)',rub(t.revenue)],['Доход',rub(t.plannedProfit)],['Получено',rub(x.received)],['Доход (факт)',rub(t.profit)],['Осталось получить',rub(t.debt)],...(t.overpayment?[['Переплата',rub(t.overpayment)]]:[])].map(([l,v])=>`<div class="fin-line"><span>${l}</span><b>${v}</b></div>`).join('')}${x.note?`<p class="footnote">${esc(x.note)}</p>`:''}<div class="actions">${btn('edit-card','Изменить',`data-id="${x.id}" class="secondary"`)}${btn('card-payment','Учесть оплату',`data-id="${x.id}" class="primary"`)}</div></article>`;}).join('')||'<section class="panel"><p class="muted">Заказов пока нет. Добавьте первый заказ на визитки.</p></section>'}</div>`;}
 function cardForm(id){const x=data.cards.find(x=>x.id===id);form(x?'Изменить заказ визиток':'Заказ визиток',field('ФИО / заказчик','name',x?.name||'','text','required maxlength="200"')+field('Дата заказа','date',x?.date||today(),'date','required')+`<div class="fields">${field('Кол-во','quantity',x?.quantity||96,'number','required min="1" step="1" max="1000000"')}${field('Кол-во (факт)','actualQuantity',x?.actualQuantity??96,'number','required min="0" step="1" max="1000000"')}${field('Цена закупки за 1 шт., ₽','unitCost',x?x.unitCost/100:2.5,'number','required min="0" step="0.01"')}${field('Цена за 1 шт. с наценкой, ₽','unitPrice',x?x.unitPrice/100:3.6,'number','required min="0" step="0.01"')}</div>`+field('Получено, ₽','received',x?x.received/100:0,'number','required min="0" step="0.01"')+`<section class="fin-card-calc panel" aria-live="polite"></section>`+field('Комментарий','note',x?.note||'','text','maxlength="500"')+'<p class="footnote">Себестоимость = кол-во × закупочная цена. Должны (факт) = фактическое кол-во × цена с наценкой. Доход = должны − себестоимость. Доход (факт) = получено − себестоимость.</p>','Сохранить заказ',f=>{const record=cardInput(f);record.id=x?.id||uid();if(x)Object.assign(x,record);else data.cards.push(record);tab='cards';});const update=()=>{const out=modal.querySelector('.fin-card-calc');try{const f=new FormData(modal.querySelector('form')),x=cardInput(f,true),t=cardTotals(x);out.innerHTML=[['Себестоимость',t.cost],['Должны (факт)',t.revenue],['Доход',t.plannedProfit],['Доход (факт)',t.profit],['Осталось получить',t.debt],...(t.overpayment?[['Переплата',t.overpayment]]:[])].map(([l,n])=>`<div class="fin-line"><span>${l}</span><b>${rub(n)}</b></div>`).join('');}catch{out.textContent='Заполните количество и цены для расчёта.';}};modal.querySelector('form').addEventListener('input',update);update();}
 function cardInput(f,preview=false){const quantity=Number(f.get('quantity')),actualQuantity=Number(f.get('actualQuantity'));if(!Number.isInteger(quantity)||quantity<1||quantity>1000000||!Number.isInteger(actualQuantity)||actualQuantity<0||actualQuantity>1000000)throw Error('Проверьте количество визиток.');const cents=k=>Number(f.get(k))===0?0:amount(f.get(k));return {name:f.get('name').trim(),date:f.get('date'),quantity,actualQuantity,unitCost:cents('unitCost'),unitPrice:cents('unitPrice'),received:cents('received'),note:f.get('note').trim()};}
 function stockView(){return `<div class="row between"><h3>Склад · ${data.stock.reduce((n,x)=>n+x.quantity,0)} шт.</h3>${btn('stock','＋ Товар','class="primary"')}</div><p class="footnote">Стоимость остатков: ${rub(data.stock.reduce((n,x)=>n+x.quantity*x.cost,0))}. Потенциальная прибыль: ${rub(data.stock.reduce((n,x)=>n+x.quantity*(x.price-x.cost),0))} — в доходы не включается.</p><div class="fin-cards">${data.stock.map(x=>`<article class="panel"><h3>${esc(x.name)}</h3><p class="muted">${esc(x.source)} · остаток ${x.quantity} шт.</p><div class="fin-line"><span>Закупка за штуку</span><b>${rub(x.cost)}</b></div><div class="fin-line"><span>Цена продажи</span><b>${rub(x.price)}</b></div>${btn('sell-stock','Продать',`data-id="${x.id}" class="secondary full" ${x.quantity?'':'disabled'}`)}</article>`).join('')}</div>`;}
 function moreView(){return `<div class="fin-duo"><section class="panel"><h3>Счета</h3>${accountSummary()}${data.accounts.map(x=>`<button class="fin-source" data-fin="account" data-id="${x.id}"><span>${esc(x.name)}</span><b>${rub(x.balance)} ✎</b></button>`).join('')}${btn('limits','Изменить долг и резерв','class="textlink"')}</section><section class="panel"><h3>Ипотеки</h3>${data.mortgages.map(x=>`<h3>${esc(x.name)}</h3><p class="fin-metric">${rub(x.balance)}</p><p class="muted">Погашено ${Math.round((1-x.balance/x.initial)*100)}%</p>${btn('mortgage','Добавить платёж',`data-id="${x.id}" class="secondary"`)}<p class="footnote">Записано платежей: ${x.payments.length}</p>`).join('')}</section><section class="panel"><h3>Семейные расчёты</h3>${data.family.map(x=>`<p>${esc(x.name)}</p><p class="fin-metric">${rub(x.balance)}</p>${btn('family','Учесть расход',`data-id="${x.id}" class="secondary"`)}<p class="footnote">Записано операций: ${x.payments.length}</p>`).join('')}</section><section class="panel"><h3>Тестовый режим</h3><p class="muted">Изменения сохраняются только в этом браузере. Реальная история Money.xlsx пока не импортирована. Синхронизацию подключим после согласования прототипа.</p>${btn('reset','Сбросить тестовые данные','class="textlink"')}</section></div>`;}
 function render(){const names={overview:'Обзор',incomes:'Доходы',sales:'Продажи',stock:'Склад',cards:'Визитки',more:'Ещё'};root.innerHTML=`<header class="topbar"><a class="brand" href="/" style="text-decoration:none;color:inherit">Свои деньги<em>.</em></a><a href="/">Все разделы ↗</a></header><main class="fin-main"><div class="heading"><div><p class="muted">Личные финансы</p><h1>Доход</h1></div>${btn('income','＋ Доход','class="primary"')}</div><div class="fin-demo"><b>Рабочий прототип · тестовые данные</b><span>Можно добавлять и менять записи. Ваши сборы в «Работе» не затрагиваются.</span></div><nav class="fin-nav" aria-label="Разделы дохода">${Object.entries(names).map(([k,v])=>btn('tab',v,`data-tab="${k}" class="${k===tab?'selected':''}"`)).join('')}</nav>${['overview','incomes'].includes(tab)?`<div class="fin-period"><label>Год<select id="fin-year">${[2025,2026,2027].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label>Период<select id="fin-month"><option value="all">Весь год</option>${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${month===String(i+1).padStart(2,'0')?'selected':''}>${new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'})}</option>`).join('')}</select></label></div>`:''}${tab==='overview'?overview():tab==='incomes'?incomesView():tab==='sales'?salesView():tab==='stock'?stockView():tab==='cards'?cardsView():moreView()}</main>`;
 root.querySelector('#fin-year')?.addEventListener('change',e=>{year=Number(e.target.value);render();});root.querySelector('#fin-month')?.addEventListener('change',e=>{month=e.target.value;render();});root.querySelector('#fin-kind')?.addEventListener('change',e=>{kind=e.target.value;render();});
 }
 function incomeForm(id){const x=data.incomes.find(x=>x.id===id);form(x?'Изменить поступление':'Добавить доход',`<label class="field">Категория<select name="category">${options(categories,x?.category||'Зарплата')}</select></label>`+field('Сумма, ₽','amount',x?x.amount/100:'','number','required min="0.01" step="0.01"')+field('Дата поступления','date',x?.date||today(),'date','required')+field('За какой месяц','month',x?.month||today().slice(0,7),'month','required')+field('Банк / счёт','bank',x?.bank||'Т-Банк','text','required maxlength="100"')+field('Комментарий','note',x?.note||'','text','maxlength="500"'),'Сохранить',f=>{const record={id:x?.id||uid(),category:f.get('category'),amount:amount(f.get('amount')),date:f.get('date'),month:f.get('month'),bank:f.get('bank').trim(),note:f.get('note').trim()};if(x)Object.assign(x,record);else data.incomes.push(record);year=Number(record.month.slice(0,4));month=record.month.slice(5);kind='all';tab='incomes';});}
 function saleForm(productId){const p=data.stock.find(x=>x.id===productId);form('Новая продажа',field('Товар / заказ','name',p?.name||'','text','required maxlength="200"')+field('Количество','quantity',1,'number',`required min="1" step="1" ${p?`max="${p.quantity}"`:''}`)+field('Сумма продажи, ₽','revenue',p?p.price/100:'','number','required min="0.01" step="0.01"')+field('Себестоимость заказа, ₽','cost',p?p.cost/100:0,'number','required min="0" step="0.01"')+field('Получено, ₽','received',p?p.price/100:'','number','required min="0" step="0.01"')+field('Дата продажи','date',today(),'date','required')+'<p class="footnote">Сумма продажи и себестоимость — за весь заказ, а не за одну штуку.</p>','Записать продажу',f=>{const quantity=Number(f.get('quantity'));if(!Number.isInteger(quantity)||quantity<1||p&&quantity>p.quantity)throw Error('Проверьте количество.');const revenue=amount(f.get('revenue')),cost=Number(f.get('cost'))===0?0:amount(f.get('cost')),received=Number(f.get('received'))===0?0:amount(f.get('received'));if(received>revenue)throw Error('Получено больше суммы продажи.');data.sales.push({id:uid(),name:f.get('name').trim(),quantity,revenue,cost,received,date:f.get('date'),productId:p?.id||''});if(p)p.quantity-=quantity;tab='sales';});}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-fin]');if(!b||b.disabled)return;const action=b.dataset.fin,id=b.dataset.id;if(action==='tab'){tab=b.dataset.tab;render();}else if(action==='income'||action==='edit-income')incomeForm(id);else if(action==='month'){month=b.dataset.month;tab='incomes';kind='all';render();}else if(action==='category'){kind=b.dataset.kind;tab='incomes';render();}else if(action==='accounts'){tab='more';render();}else if(action==='card'||action==='edit-card')cardForm(id);else if(action==='card-payment'){const x=data.cards.find(x=>x.id===id),t=cardTotals(x);form('Оплата визиток',field('Сумма оплаты, ₽','amount',t.debt?t.debt/100:'','number','required min="0.01" step="0.01"'),'Учесть оплату',f=>{x.received+=amount(f.get('amount'));});}else if(action==='sale'||action==='sell-stock')saleForm(id);else if(action==='stock')form('Добавить товар',field('Название','name','','text','required maxlength="200"')+field('Количество','quantity',1,'number','required min="1" step="1"')+field('Закупка за штуку, ₽','cost',0,'number','required min="0" step="0.01"')+field('Цена за штуку, ₽','price','','number','required min="0.01" step="0.01"')+field('Источник','source','','text','maxlength="100"'),'Добавить',f=>{const quantity=Number(f.get('quantity'));if(!Number.isInteger(quantity)||quantity<1)throw Error('Укажите целое количество.');data.stock.push({id:uid(),name:f.get('name').trim(),quantity,cost:Number(f.get('cost'))===0?0:amount(f.get('cost')),price:amount(f.get('price')),source:f.get('source')});});else if(action==='sale-pay'){const x=data.sales.find(x=>x.id===id);form('Оплата продажи',field('Получить, ₽','amount',(x.revenue-x.received)/100,'number','required min="0.01" step="0.01"'),'Учесть оплату',f=>{const n=amount(f.get('amount'));if(n>x.revenue-x.received)throw Error('Сумма больше долга.');x.received+=n;});}else if(action==='account'){const x=data.accounts.find(x=>x.id===id);form('Остаток на счёте',field('Название','name',x.name,'text','required')+field('Остаток, ₽','balance',x.balance/100,'number','required min="0" step="0.01"'),'Сохранить',f=>{x.name=f.get('name');x.balance=Number(f.get('balance'))===0?0:amount(f.get('balance'));});}else if(action==='limits')form('Обязательства',field('Долг по кредиткам, ₽','credit',data.credit/100,'number','required min="0" step="0.01"')+field('Резерв, ₽','reserved',data.reserved/100,'number','required min="0" step="0.01"'),'Сохранить',f=>{for(const k of ['credit','reserved'])data[k]=Number(f.get(k))===0?0:amount(f.get(k));});else if(action==='mortgage'||action==='family'){const x=data[action==='mortgage'?'mortgages':'family'].find(x=>x.id===id);form(action==='mortgage'?'Ипотечный платёж':'Семейный расчёт',field(action==='mortgage'?'Основной долг, ₽':'Сумма расхода, ₽','amount','','number','required min="0.01" step="0.01"')+(action==='mortgage'?field('Проценты, ₽','interest',0,'number','required min="0" step="0.01"'):'')+field('Дата','date',today(),'date','required')+field('Комментарий','note','','text','maxlength="500"'),'Записать',f=>{const n=amount(f.get('amount'));if(n>x.balance)throw Error('Сумма больше остатка долга.');x.balance-=n;x.payments.push({id:uid(),amount:n,interest:Number(f.get('interest')||0)===0?0:amount(f.get('interest')),date:f.get('date'),note:f.get('note')});});}else if(action==='reset')form('Сбросить примеры','<p>Все изменения тестового раздела «Доход» в этом браузере будут заменены исходными примерами. Данные «Работы» сохранятся.</p>','Сбросить',()=>{data=demoFinance();data.cards=data.sales.filter(x=>x.name.startsWith('Визитки')).map(x=>({id:x.id,name:'Тестовый заказчик',date:x.date,quantity:x.quantity,actualQuantity:x.quantity,unitCost:Math.round(x.cost/x.quantity),unitPrice:Math.round(x.revenue/x.quantity),received:x.received,note:''}));data.sales=data.sales.filter(x=>!x.name.startsWith('Визитки'));tab='overview';year=2026;month='all';});});render();
}
